# Generated by OrcaCloud for a resource-textures plugin.
# OrcaSlicer lists the images in t/ in its texture displacement picker.
import os

import orca

# Slicers without resource texture plugins cannot use this pack; say so
# instead of failing on a missing name.
if not hasattr(orca, "resource_texture"):
    raise ImportError(
        "This texture pack needs an OrcaSlicer version that supports resource texture plugins."
    )

TEXTURE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "t")


class Textures(orca.resource_texture.ResourceTexturePluginCapabilityBase):
    def get_name(self):
        return "BumpMesh Textures by xcaliburr101"

    def get_texture_dir(self):
        return TEXTURE_DIR


@orca.plugin
class TexturePack(orca.base):
    def register_capabilities(self):
        orca.register_capability(Textures)
